(function(root){
  const KEY='word-notes-workspace-v2',LEGACY='word-notes-notebook-v1';
  function id(){return root.crypto?.randomUUID?.()||'note-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)}
  function cleanRow(r){if(!r||typeof r.word!=='string'||typeof r.meaning!=='string')throw Error('笔记格式无效');return{id:id(),word:r.word,meaning:r.meaning,remark:typeof r.remark==='string'?r.remark:'',source:typeof r.source==='string'?r.source:'unknown'}}
  function project(name='未命名项目',rows=[]){return{id:id(),name:name.trim()||'未命名项目',rows:rows.map(cleanRow),updatedAt:new Date().toISOString()}}
  function validate(data){if(!data||data.schemaVersion!==2||!Array.isArray(data.projects)||!data.projects.length)throw Error('不是有效的完整项目备份');const ids=new Set();const projects=data.projects.map(p=>{if(!p||typeof p.id!=='string'||!p.id||ids.has(p.id)||typeof p.name!=='string'||!Array.isArray(p.rows))throw Error('项目格式无效');ids.add(p.id);return{...project(p.name,p.rows),id:p.id}});return{schemaVersion:2,activeProjectId:ids.has(data.activeProjectId)?data.activeProjectId:projects[0].id,projects}}
  function create(storage,embedded=null){let state,loadError=null;try{const raw=storage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));else if(embedded?.projects)state=validate(embedded);else{const legacy=JSON.parse(storage.getItem(LEGACY)||'null');const p=project(legacy?.title||'我的第一个项目',Array.isArray(legacy?.rows)?legacy.rows:[]);state={schemaVersion:2,activeProjectId:p.id,projects:[p]}}}catch(e){loadError=e;try{state=validate(embedded)}catch{const p=project();state={schemaVersion:2,activeProjectId:p.id,projects:[p]}}}
    const api={get state(){return state},get loadError(){return loadError},active(){return state.projects.find(p=>p.id===state.activeProjectId)},persist(){if(loadError)throw Error('无法读取原有数据，当前内容仅在内存中，请先备份或恢复');storage.setItem(KEY,JSON.stringify(state))},add(name){const p=project(name);state.projects.push(p);state.activeProjectId=p.id;return p},switchTo(pid){if(!state.projects.some(p=>p.id===pid))throw Error('项目不存在');state.activeProjectId=pid},rename(name){api.active().name=name.trim()||'未命名项目';api.active().updatedAt=new Date().toISOString()},backup(){return JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)},importData(input){let incoming;if(input?.schemaVersion===2)incoming=validate(input).projects;else if(input&&Array.isArray(input.rows)){incoming=[project(typeof input.title==='string'?input.title:'导入的笔记',input.rows)]}else throw Error('请选择完整项目备份或笔记 JSON');const added=incoming.map(p=>project(p.name,p.rows));state.projects.push(...added);state.activeProjectId=added[0].id;loadError=null;return added}};
    return api;
  }
  root.WorkspaceCore={create,validate,project,id};
})(globalThis);
